body.query:
query {
  r0: repository(owner:"abhishek-chattopadhyay", name:"robot") { ...repoBits }
  r1: repository(owner:"BioDataFuse", name:"pyBiodatafuse") { ...repoBits }
  r2: repository(owner:"BioDataFuse", name:"biodatafuseUI") { ...repoBits }
  r3: repository(owner:"bridgedb", name:"datasources") { ...repoBits }
  r4: repository(owner:"bridgedb", name:"BridgeDb") { ...repoBits }
  r5: repository(owner:"bridgedb", name:"BridgeDbWebservice") { ...repoBits }
  r6: repository(owner:"bridgedb", name:"bridgedbjs") { ...repoBits }
  r7: repository(owner:"bridgedb", name:"docker") { ...repoBits }
  r8: repository(owner:"BiGCAT-UM", name:"BridgeDbR") { ...repoBits }
  r9: repository(owner:"wikipathways", name:"rWikiPathways") { ...repoBits }
}

fragment repoBits on Repository {
  nameWithOwner pushedAt isArchived stargazerCount
  primaryLanguage { name }
  licenseInfo { spdxId }
  releases(first:100, orderBy:{field:CREATED_AT, direction:DESC}) {
    nodes { tagName publishedAt isDraft }
  }
  refs(refPrefix:"refs/tags/", first:100,
       orderBy:{field:TAG_COMMIT_DATE, direction:DESC}) {
    nodes { name target { ... on Commit { committedDate }
                          ... on Tag { target { ... on Commit { committedDate } } } } }
  }
}
